40	async function fetchFavoritesEvents(
41	  slugs: string[]
42	): Promise<{ events: EventSummaryResponseDTO[]; notFoundSlugs: string[] }> {
43	  const uniqueSlugs = Array.from(new Set(slugs)).slice(0, MAX_FAVORITES);
44	  const results: EventSummaryResponseDTO[] = [];
45	  const notFoundSlugs: string[] = [];
46	
47	  const reasonToString = (reason: unknown): string => {
48	    if (reason instanceof Error) return reason.message;
49	    if (typeof reason === "string") return reason;
50	
51	    try {
52	      return JSON.stringify(reason);
53	    } catch {
54	      return "unknown";
55	    }
56	  };
57	
58	  for (let i = 0; i < uniqueSlugs.length; i += FETCH_CONCURRENCY) {
59	    const chunk = uniqueSlugs.slice(i, i + FETCH_CONCURRENCY);
60	    const fetched = await Promise.allSettled(
61	      chunk.map((slug) => fetchEventBySlugWithStatus(slug))
62	    );
63	
64	    const failedFetches: Array<{ slug: string | undefined; reason: unknown }> =
65	      [];
66	
67	    for (let j = 0; j < fetched.length; j++) {
68	      const slug = chunk[j];
69	      const settled = fetched[j];
70	      if (settled.status !== "fulfilled") {
71	        failedFetches.push({ slug, reason: settled.reason });
72	        continue;
73	      }
74	
75	      const { event, notFound } = settled.value;
76	
77	      if (notFound && slug) {
78	        notFoundSlugs.push(slug);
79	      }
80	
81	      if (event != null) {
82	        results.push(event);
83	      }
84	    }
85	
86	    if (failedFetches.length > 0) {
87	      captureException(new Error("Favorites: fetch failures"), {
88	        tags: {
89	          feature: "favorites",
90	          page: "/preferits",
91	          phase: "fetch_event_by_slug",
92	        },
93	        extra: {
94	          failedCount: failedFetches.length,
95	          failedSlugs: failedFetches.map((f) => f.slug).filter(Boolean),
96	          failedReasons: failedFetches.map((f) => reasonToString(f.reason)),
97	        },
98	      });
99	    }
100	  }
101	
102	  return { events: results, notFoundSlugs };
103	}
104	
105	function collectExpiredEventKeys<K>(
106	  events: EventSummaryResponseDTO[],
107	  keyOf: (event: EventSummaryResponseDTO) => K | null | undefined
108	): K[] {
109	  return events.flatMap((event) => {
110	    const key = keyOf(event);
111	    if (!key) return [];
112	    if (isEventActive(event)) return [];
113	    return [key];
114	  });
115	}
116	
117	export default async function PreferitsPage() {
118	  const locale = (await rootLocale()) as AppLocale;
119	  const t = await getTranslations({ locale, namespace: "App.Favorites" });
120	
121	  const authToken = await getAccessTokenFromCookies();
122	
123	  let events: EventSummaryResponseDTO[];
124	  let uniqueFavoritesCount: number;
125	  let slugsToRemove: string[];
126	  let eventIdsToRemove: string[];
127	  let backendUnavailable = false;
