1	// HttpOnly cookie storage for the Logto OIDC session. Tokens never reach
2	// client JS. The access token keeps the `auth_token` cookie name so existing
3	// consumers (favorites, events, preferits) read the session unchanged via
4	// getAccessTokenFromCookies().
5	//
6	// When LOGTO_COOKIE_SECRET is set, the token cookie *values* are additionally
7	// encrypted at rest with AES-256-GCM (Logto's SDK default). It's optional and
8	// backwards-compatible: unset → plaintext; a legacy plaintext cookie is still
9	// readable after the secret is introduced (graceful rollout).
10	import "server-only";
11	import { cookies } from "next/headers";
12	import type { NextRequest, NextResponse } from "next/server";
13	import {
14	  createCipheriv,
15	  createDecipheriv,
16	  createHash,
17	  randomBytes,
18	} from "node:crypto";
19	import type { FlowState, LogtoTokenResponse, TokenCookieWrite } from "types/auth";
20	
21	export const ACCESS_TOKEN_COOKIE = "auth_token";
22	export const REFRESH_TOKEN_COOKIE = "auth_refresh_token";
23	export const ID_TOKEN_COOKIE = "logto_id_token";
24	
25	export const STATE_COOKIE = "logto_state";
26	export const CODE_VERIFIER_COOKIE = "logto_code_verifier";
27	export const NONCE_COOKIE = "logto_nonce";
28	export const RETURN_TO_COOKIE = "logto_return_to";
29	
30	// Refresh token / id_token outlive the access token; cap session length here.
31	const SESSION_MAX_AGE = 60 * 60 * 24 * 30; // 30 days
32	const FLOW_MAX_AGE = 60 * 10; // 10 minutes
33	// 2026-07-26: Logto's default access_token lifetime is 3600s. We use this as
34	// a defensive fallback when the token response omits `expires_in` or returns
35	// a non-positive value. `response.cookies.set({ maxAge: 0 })` instantly
36	// expires the cookie; `maxAge: undefined` makes it a session cookie that
37	// browsers drop on close. Either way, the auth_token cookie disappears
38	// while the id_token cookie (which uses SESSION_MAX_AGE hardcoded) survives
39	// — producing the silent "logged in but 401 on every mutation" failure the
40	// user hit after a silent SSO re-login on 2026-07-26.
41	const ACCESS_TOKEN_DEFAULT_MAX_AGE = 60 * 60; // 1 hour
42	
43	const IS_PRODUCTION = process.env.NODE_ENV === "production";
44	
45	const baseOptions = {
46	  httpOnly: true,
47	  secure: IS_PRODUCTION,
48	  // Lax so cookies are sent on Logto's top-level GET redirect back to /callback.
49	  sameSite: "lax" as const,
50	};
51	
52	// ── At-rest encryption (optional) ─────────────────────────────
53	const ENC_PREFIX = "v1.";
54	
55	// Resolve the AES key lazily on first cookie access (not at module load) so a
56	// missing/short secret fails the request, not the whole build/import — this
57	// module is imported app-wide. A >=32-char random secret keyed via SHA-256 to
58	// a 32-byte AES key is sufficient (no stretching of a server-side secret).
59	let encKeyCache: Buffer | null | undefined;
60	function getEncKey(): Buffer | null {
61	  if (encKeyCache !== undefined) return encKeyCache;
62	  const cookieSecret = process.env.LOGTO_COOKIE_SECRET;
63	  // 2026-07-26 round-9: log the secret length (never the value) once so a
64	  // future "decrypt returns null but cookie is present" debug can tell from
65	  // one grep whether the encryption key was actually initialised at all.
66	  console.log(
67	    `[AUTH DIAGNOSTIC] getEncKey initialized: secret length=${cookieSecret?.length ?? 0}`,
68	  );
69	  if (cookieSecret && cookieSecret.length < 32) {
70	    throw new Error("LOGTO_COOKIE_SECRET must be at least 32 characters");
71	  }
72	  if (!cookieSecret && IS_PRODUCTION) {
73	    console.warn(
74	      "[auth-cookies] LOGTO_COOKIE_SECRET is not set — session tokens are stored unencrypted",
75	    );
76	  }
77	  encKeyCache = cookieSecret
78	    ? createHash("sha256").update(cookieSecret).digest()
79	    : null;
80	  return encKeyCache;
81	}
82	
83	function encrypt(plaintext: string): string {
84	  const encKey = getEncKey();
85	  if (!encKey) return plaintext;
86	  const iv = randomBytes(12);
87	  const cipher = createCipheriv("aes-256-gcm", encKey, iv);
88	  const enc = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
89	  const tag = cipher.getAuthTag();
90	  return ENC_PREFIX + Buffer.concat([iv, tag, enc]).toString("base64url");
91	}
92	
93	function decrypt(value: string | undefined): string | null {
94	  // 2026-07-26 round-9 diagnostic: log every decrypt outcome so a
95	  // "decrypt returns null but cookie is present" symptom (round-9 publish
96	  // failure) can be root-caused in one grep. Never log the value itself.
97	  if (!value) {
98	    console.log("[AUTH DIAGNOSTIC] decrypt: cookie value is undefined");
99	    return null;
100	  }
101	  const encKey = getEncKey();
102	  if (!encKey) {
103	    // A v1.* envelope with no key configured means the secret was removed or
104	    // mistyped — don't pass the encrypted blob through as a bearer token.
105	    console.log(
106	      `[AUTH DIAGNOSTIC] decrypt: encKey is null at read-time, value prefix=${value.slice(0, ENC_PREFIX.length + 4)}`,
107	    );
108	    return value.startsWith(ENC_PREFIX) ? null : value;
109	  }
110	  // Legacy plaintext cookie written before the secret was introduced.
111	  if (!value.startsWith(ENC_PREFIX)) {
112	    console.log("[AUTH DIAGNOSTIC] decrypt: plaintext value, returning as-is");
113	    return value;
114	  }
115	  try {
116	    const buf = Buffer.from(value.slice(ENC_PREFIX.length), "base64url");
117	    const iv = buf.subarray(0, 12);
118	    const tag = buf.subarray(12, 28);
119	    const enc = buf.subarray(28);
120	    const decipher = createDecipheriv("aes-256-gcm", encKey, iv);
121	    decipher.setAuthTag(tag);
122	    const result = Buffer.concat([decipher.update(enc), decipher.final()]).toString(
123	      "utf8",
124	    );
125	    console.log("[AUTH DIAGNOSTIC] decrypt: SUCCESS");
126	    return result;
127	  } catch (err) {
128	    // 2026-07-26 round-9: the round-9 hypothesis — encryption key rotation
129	    // between write-time (login) and read-time (publish Server Action) —
130	    // surfaces here. AES-256-GCM's tag mismatch is the symptom.
131	    console.log(
132	      `[AUTH DIAGNOSTIC] decrypt: FAILED (likely key mismatch between write & read) - ${err instanceof Error ? err.message : String(err)}`,
133	    );
134	    return null;
135	  }
136	}
137	
138	/** Read access token from incoming request cookies (server components + routes). */
139	export async function getAccessTokenFromCookies(): Promise<string | null> {
140	  const cookieStore = await cookies();
141	  return decrypt(cookieStore.get(ACCESS_TOKEN_COOKIE)?.value);
142	}
143	
144	/** Read id_token from incoming request cookies (server components + routes). */
145	export async function getIdTokenFromCookies(): Promise<string | null> {
146	  const cookieStore = await cookies();
147	  return decrypt(cookieStore.get(ID_TOKEN_COOKIE)?.value);
148	}
149	
150	/** Read and decrypt a token cookie from a route handler's NextRequest. */
151	export function readTokenFromRequest(
152	  request: NextRequest,
153	  name: string,
154	): string | null {
155	  return decrypt(request.cookies.get(name)?.value);
156	}
157	
158	// Shared by setTokenCookies (route handlers holding a NextResponse) and
159	// getValidAccessToken (Server Actions / route handlers that only have the
160	// cookies() API) so the two writers can't drift on maxAge/path/encryption.
161	function buildTokenCookieWrites(tokens: LogtoTokenResponse): TokenCookieWrite[] {
162	  // 2026-07-26: defensively coerce `expires_in` to a positive integer. See
163	  // ACCESS_TOKEN_DEFAULT_MAX_AGE for the rationale (silent SSO path
164	  // produced a missing-auth_token state on 2026-07-26).
165	  const rawExpiresIn = tokens.expires_in;
166	  const safeMaxAge =
167	    typeof rawExpiresIn === "number" && rawExpiresIn > 0
168	      ? rawExpiresIn
169	      : ACCESS_TOKEN_DEFAULT_MAX_AGE;
170	  const encryptedAccessToken = encrypt(tokens.access_token);
171	  // Diagnostic: log the chosen maxAge + encrypted payload length so a future
172	  // "auth_token cookie missing" regression can be root-caused in one grep.
173	  // Browsers drop cookies > 4096 bytes per cookie; if the encrypted
174	  // access_token approaches that limit, the bug is JWT bloat, not the
175	  // maxAge fallback.
176	  console.log(
177	    `[AUTH DIAGNOSTIC] setTokenCookies: expires_in=${rawExpiresIn} -> maxAge=${safeMaxAge}s; auth_token encrypted length=${encryptedAccessToken.length} bytes (browsers drop cookies > 4096 bytes)`,
178	  );
179	  const writes: TokenCookieWrite[] = [
180	    {
181	      name: ACCESS_TOKEN_COOKIE,
182	      value: encryptedAccessToken,
183	      options: { ...baseOptions, path: "/", maxAge: safeMaxAge },
184	    },
185	  ];
186	  // Refresh-token responses may omit id_token; keep the existing one rather
187	  // than overwriting it (the id_token_hint is needed for RP-initiated logout).
188	  if (tokens.id_token) {
189	    writes.push({
190	      name: ID_TOKEN_COOKIE,
191	      value: encrypt(tokens.id_token),
192	      options: { ...baseOptions, path: "/", maxAge: SESSION_MAX_AGE },
193	    });
194	  }
195	  if (tokens.refresh_token) {
196	    // path: "/" (not "/api/auth") — Server Actions bound to arbitrary pages
197	    // (e.g. createEventAction on /publica) need this cookie to refresh an
198	    // expired access token, and the browser only attaches a cookie to
199	    // requests matching its path scope. Still HttpOnly + Secure + SameSite=
200	    // Lax throughout; only our own same-origin server code ever reads it.
201	    //
202	    // Sessions from before this path moved from /api/auth to / still carry
203	    // the old-scoped cookie in their browser; it stops being read/rotated
204	    // but isn't actively harmful (a same-named cookie at a different path is
205	    // a separate entry) and is fully cleared at next logout — see
206	    // clearTokenCookies. Not cleared here too: NextResponse's cookie jar
207	    // keys by name, so a second `.set()` for the same name in one response
208	    // would silently replace this write instead of emitting a second
209	    // Set-Cookie header.
210	    writes.push({
211	      name: REFRESH_TOKEN_COOKIE,
212	      value: encrypt(tokens.refresh_token),
213	      options: { ...baseOptions, path: "/", maxAge: SESSION_MAX_AGE },
214	    });
215	  }
216	  return writes;
217	}
218	
219	export function setTokenCookies(
220	  response: NextResponse,
221	  tokens: LogtoTokenResponse,
222	): void {
223	  for (const write of buildTokenCookieWrites(tokens)) {
224	    response.cookies.set(write.name, write.value, write.options);
225	  }
226	}
227	
228	/**
229	 * Returns a usable access token for mutation call sites (Server Actions and
230	 * Route Handlers), refreshing it via the refresh_token cookie when the
231	 * (shorter-lived, ~1h) access_token cookie has expired.
232	 *
233	 * Without this, a session that's still fully valid (the 30-day id_token
234	 * cookie is fine) 401s on every mutation once the access token ages out,
235	 * while GETs/page loads look completely normal — the "still logged in, but
236	 * Authentication required on submit" bug. `GET /api/auth/me` already refreshes
237	 * transparently; this extends the same behavior to POST/PATCH/DELETE
238	 * mutations (event create/update/delete, profile, avatar, favorites), which
239	 * previously read the access token cookie directly and gave up immediately.
240	 *
241	 * Returns null (caller should 401) only when there's no refresh_token either,
242	 * or the refresh itself fails (revoked/expired refresh token, Logto outage).
243	 */
244	export async function getValidAccessToken(): Promise<string | null> {
245	  const existing = await getAccessTokenFromCookies();
246	  if (existing) return existing;
247	
248	  const cookieStore = await cookies();
249	  const refreshToken = decrypt(cookieStore.get(REFRESH_TOKEN_COOKIE)?.value);
250	  if (!refreshToken) return null;
